def merge_sorted(a, b):
    result = []
    i = j = 0
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            result.append(a[i])
            i += 1
        else:
            result.append(b[j])
            j += 1
    result.extend(a[i:])
    result.extend(b[j:])
    return result

def chunked(values, size):
    if size <= 0:
        raise ValueError("size must be positive")
    if not values:
        return []
    result = []
    for i in range(0, len(values), size):
        result.append(values[i:i + size])
    return result

