def merge_tool_results(calls, results):
    # Validate no duplicate call ids
    seen = set()
    for call in calls:
        cid = call['id']
        if cid in seen:
            raise ValueError(f"duplicate call id: {cid}")
        seen.add(cid)

    # Build a mapping from id -> last result (list of results, last wins)
    last_result = {}
    for res in results:
        rid = res['id']
        # Only consider results with ids that are in calls
        if rid in seen:
            last_result[rid] = res

    # Build output in call order
    output = []
    for call in calls:
        cid = call['id']
        if cid in last_result:
            content = last_result[cid].get('content', '')
            output.append({'id': cid, 'status': 'done', 'content': content})
        else:
            output.append({'id': cid, 'status': 'pending'})
    return output

