def merge_tool_results(calls, results):
    # Validate no duplicate call ids in calls
    call_ids = [c.get('id') for c in calls]
    if len(call_ids) != len(set(call_ids)):
        raise ValueError("duplicate call ids")

    # Build a mapping from id to the last result content
    last_result = {}
    for res in results:
        rid = res.get('id')
        if rid is not None and rid in call_ids:
            last_result[rid] = res.get('content', '')

    # Build output in call order
    output = []
    for call in calls:
        cid = call.get('id')
        if cid in last_result:
            output.append({'id': cid, 'status': 'done', 'content': last_result[cid]})
        else:
            output.append({'id': cid, 'status': 'pending'})

    return output

