def trim_history(messages, budget):
    if budget < 0:
        raise ValueError("budget must be nonnegative")
    for msg in messages:
        cost = msg.get('cost')
        if cost is None:
            raise ValueError("message must have a cost")
        if cost < 0:
            raise ValueError("cost must be nonnegative")
    n = len(messages)
    if n == 0:
        return []
    total = sum(msg['cost'] for msg in messages)
    if total <= budget:
        return list(messages)
    cumulative = 0
    start = n
    for i in range(n - 1, -1, -1):
        cumulative += messages[i]['cost']
        if cumulative > budget:
            break
        start = i
    return messages[start:]

