def merge_tool_results(calls, results):
    # Extract call ids in order
    call_ids = [c['id'] for c in calls]

    # Reject duplicate call ids
    if len(call_ids) != len(set(call_ids)):
        raise ValueError("duplicate call ids")

    # Build mapping from id to content (last result wins)
    content_map = {}
    for result in results:
        id_ = result['id']
        if id_ in call_ids:
            content_map[id_] = result.get('content', '')

    # Build output in call order
    output = []
    for id_ in call_ids:
        if id_ in content_map:
            output.append({'id': id_, 'status': 'done', 'content': content_map[id_]})
        else:
            output.append({'id': id_, 'status': 'pending'})

    return output

